export const VERSION='1.0.0', STORAGE_KEY='qf-studio-chapter-03-v1';
export const STEPS=[['start','Prepare your data desk',10],['provenance','Know the source',20],['order','Order before calculating',25],['quality','Investigate quality',30],['adjustment','Explain a split',25],['lab','Build an audit trail',35],['assessment','Transfer to a new file',25],['finish','Save a data card',10]];
export const RAW=[{date:'2025-01-08',raw:52.02,adjusted:52.02},{date:'2025-01-03',raw:102,adjusted:51},{date:'2025-01-02',raw:100,adjusted:50},{date:'2025-01-07',raw:51,adjusted:51},{date:'2025-01-03',raw:103,adjusted:51.5},{date:'2025-01-06',raw:null,adjusted:null},{date:'2025-01-08',raw:52.02,adjusted:52.02}];
export const TRANSFER=[{date:'2025-02-06',raw:103.02,adjusted:103.02},{date:'2025-02-01',raw:200,adjusted:100},{date:'2025-02-05',raw:101,adjusted:101},{date:'2025-02-02',raw:202,adjusted:101}];
export function dateOK(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T00:00:00Z');return Number.isFinite(+d)&&d.toISOString().slice(0,10)===s;}
export function audit(rows){if(!Array.isArray(rows)||!rows.length)throw Error('Supply observations.');const groups=new Map(),issues=[];for(const r of rows){if(!dateOK(r.date))throw Error('Use valid ISO dates YYYY-MM-DD.');if(!groups.has(r.date))groups.set(r.date,[]);groups.get(r.date).push({...r});}const clean=[];for(const[date,group]of [...groups].sort(([a],[b])=>a.localeCompare(b))){const unique=[...new Map(group.map(r=>[JSON.stringify([r.raw,r.adjusted]),r])).values()];if(unique.length>1){issues.push({date,kind:'conflict',removed:group.length,reason:'Quarantined all conflicting values; original source needed.'});continue;}const r=unique[0];if(![r.raw,r.adjusted].every(v=>typeof v==='number'&&Number.isFinite(v)&&v>0)){issues.push({date,kind:'missing',removed:group.length,reason:'Missing or invalid price; no invented fill.'});continue;}if(group.length>1)issues.push({date,kind:'exact duplicate',removed:group.length-1,reason:'Identical date and prices; retain one copy.'});clean.push(r);}return {clean,issues,input:rows.length,retained:clean.length,removed:rows.length-clean.length};}
export function intervalReturns(rows,column='adjusted'){if(!['raw','adjusted'].includes(column))throw Error('Choose raw or adjusted.');if(rows.length<2)throw Error('Need at least two valid observations.');for(let i=0;i<rows.length;i++){if(!dateOK(rows[i].date)||!Number.isFinite(rows[i][column])||rows[i][column]<=0||(i&&rows[i].date<=rows[i-1].date))throw Error('Use positive prices in strictly increasing unique date order.');}return rows.slice(1).map((r,i)=>({from:rows[i].date,to:r.date,pct:(r[column]/rows[i][column]-1)*100}));}
export function cumulative(returns){return(returns.reduce((v,r)=>v*(1+r.pct/100),1)-1)*100;}
const q=(id,title,options,answer,why)=>({id,title,options,answer,why});
export const TASKS={
provenance:[q('p1','A downloaded file says “adjusted”. What must you establish?',['Assume every provider means dividends and splits','Read its adjustment convention, units, dates, source and retrieval/version notes','Only count rows'],1,'Adjustment definitions differ. Here the dictionary explicitly says split-adjusted only; dividends are absent.'),q('p2','This chapter CSV is…',['Actual exchange prices','A synthetic teaching file with no observed market history','A prediction'],1,'All values and dates are invented, with no live-market claim.')],
order:[q('o1','Which order is needed before consecutive returns?',['File order','Price ascending','Unique dates in chronological order'],2,'Sort dates, resolve duplicate ambiguity, then compute adjacent observations.'),q('o2','A return spanning 2 January to 7 January should be labelled…',['A daily return','The observed interval 2 January → 7 January','An annual return'],1,'A gap changes the interval. There is no evidence for intermediate daily moves.')],
quality:[q('q1','The same date has prices 102 and 103. No authoritative correction is available.',['Keep whichever appears last','Quarantine both and record unresolved source ambiguity','Average automatically'],1,'Keeping or averaging without evidence invents a resolution. Quarantine is a conservative teaching policy, not a universal rule.'),q('q2','The 6 January observation has no price.',['Fill with 0','Treat a filled value as a new market observation','Exclude it transparently; preserve the gap'],2,'Zero is a real value, not a missing-data marker. Filling would impose an assumption and does not reveal the unobserved path.')],
adjustment:[q('s1','A two-for-one split changes one £102 share to two £51 shares. Wealth change due only to the split?',['−50%','0%','+100%'],1,'Before: one × £102. After: two × £51 = £102. The share count doubles.'),q('s2','Our split-adjusted series excludes dividends. It measures…',['Total return including every distribution','Split-consistent price return only','A guaranteed strategy return'],1,'The file adjusts old prices for the stated split. No dividends means it is not a dividend-inclusive total-return series.')]
};
export const ASSESSMENT=[q('a1','New file arrives in order 6, 1, 5, 2 February. First calculation step?',['Compute returns immediately','Sort unique dates and verify source/quality','Sort prices'],1,'Chronological date order prevents backward-time returns.'),q('a2','A raw £202 to £101 move coincides with a verified two-for-one split. What explains it?',['Half the investor wealth necessarily vanished','The price per share halved while share count doubled','The adjusted return must be +100%'],1,'Corporate action changes units; use consistent adjusted prices for the price-return comparison.'),q('a3','Adjusted prices 100,101,101,103.02. Cumulative return?',['3.02%','3.00%','103.02%'],0,'(103.02 / 100 − 1) × 100 = 3.02%. The interval returns are 1%, 0%, 2%; compound them.'),q('a4','You lack an expected trading calendar. What can date spacing alone establish?',['Every gap is a data error','The observation interval, not whether an exchange should have opened','Missing returns are zero'],1,'Verify the instrument calendar and timezone before declaring missing sessions. These are synthetic dates.'),q('a5','What belongs in the exported audit?',['Only the final attractive return','Original inputs, every removal reason, conventions, calculation intervals and limitations','An unsupported promise of completeness'],1,'An audit makes transformations reviewable; it does not recover missing source evidence.')];
export const freshState=()=>({version:VERSION,fields:{},done:{},checked:{},practiceAttempts:[],attempts:[],runs:[],lastPage:'start'});
export const answerOK=(q,v)=>typeof v==='string'&&v!==''&&Number(v)===q.answer;
export function grade(answers){const details=ASSESSMENT.map(q=>({id:q.id,correct:answerOK(q,answers[q.id])}));return{details,score:details.filter(x=>x.correct).length,passed:details.every(x=>x.correct)};}
export function invalidate(s,id){s.done.finish=false;if(id==='setup')s.done.start=false;for(const[step,qs]of Object.entries(TASKS))if(qs.some(q=>q.id===id)||id===step+'Reflection'||id===step+'Criteria'){s.done[step]=false;if(qs.some(q=>q.id===id))delete s.checked[id];}if(['policy','column','prediction','hand','labReflection','labCriteria'].includes(id))s.done.lab=false;if(id.startsWith('a')||id==='revision')s.done.assessment=false;}
export function labEvidence(s){return s.fields.policy==='quarantine'&&['raw','adjusted'].every(c=>s.runs.some(r=>r.column===c))&&s.runs.some(r=>r.prediction===s.fields.prediction)&&String(s.fields.hand??'').trim()!==''&&Math.abs(Number(s.fields.hand)-2)<.011&&String(s.fields.labReflection||'').trim().length>=40&&s.fields.labCriteria===true;}
export function restoreState(raw){try{const s=JSON.parse(raw),record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(s.version!==VERSION||!record(s.fields)||!Object.values(s.fields).every(v=>typeof v==='string'||typeof v==='boolean')||!Array.isArray(s.attempts)||!Array.isArray(s.runs))return freshState();const t={...freshState(),fields:s.fields,lastPage:STEPS.some(([id])=>id===s.lastPage)?s.lastPage:'start'};for(const[step,qs]of Object.entries(TASKS)){for(const q of qs)t.checked[q.id]=answerOK(q,s.fields[q.id]);t.done[step]=s.done?.[step]===true&&qs.every(q=>t.checked[q.id])&&String(s.fields[step+'Reflection']||'').trim().length>=30&&s.fields[step+'Criteria']===true;}t.done.start=s.done?.start===true&&s.fields.setup===true;t.attempts=s.attempts.filter(a=>record(a)&&record(a.answers)&&Object.values(a.answers).every(v=>typeof v==='string')&&typeof a.time==='string'&&(a.revision===undefined||typeof a.revision==='string')).map(a=>({...a,...grade(a.answers)}));t.practiceAttempts=(Array.isArray(s.practiceAttempts)?s.practiceAttempts:[]).filter(a=>record(a)&&typeof a.time==='string'&&Array.isArray(a.answers));t.runs=s.runs.filter(r=>record(r)&&typeof r.prediction==='string'&&['raw','adjusted'].includes(r.column)&&typeof r.time==='string').map(r=>({...r,result:intervalReturns(audit(RAW).clean,r.column)}));t.done.lab=s.done?.lab===true&&labEvidence(t);const a=t.attempts.at(-1);t.done.assessment=s.done?.assessment===true&&!!a?.passed&&ASSESSMENT.every(q=>a.answers[q.id]===s.fields[q.id])&&String(s.fields.revision||'').trim().length>=30;t.done.finish=s.done?.finish===true&&STEPS.slice(0,-1).every(([id])=>t.done[id])&&['cardSource','cardMethod','cardLimits'].every(k=>String(s.fields[k]||'').trim().length>=30)&&s.fields.cardCriteria===true;return t;}catch{return freshState();}}
